    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, k;
    cin >> n >> k;

    string a;
    cin >> a;

    int t = a.find('T');
    int g = a.find('G');

    int current = min(t, g);
    int target = max(t, g);

    while (current < target) {
        current += k;

        if (current == target) {
            cout << "YES\n";
            return 0;
        }

        if (current >= n || current > target || a[current] == '#') {
            cout << "NO\n";
            return 0;
        }
    }

    cout << "NO\n";
    return 0;
}

